                                       // Stack pointer rollback arithmetic
                                       
                                       inline uintptr_t tech_2601_rollback_stack(uintptr_t current_sp, uint32_t shadow_alloc_size) {
                                       
                                           // In downward-growing stack (x86-64/ARM64), global unwind restored frame by adding alloc_size.
                                           // Rollback subtracts the shadow allocation to return SP to inner frame state.
                                           
                                           #if defined(_WIN32) || defined(_WIN64)
                                           uintptr_t target_sp = ((current_sp - shadow_alloc_size) & (~(static_cast<uintptr_t>(0x000000000000000fULL))));
                                           return target_sp;
                                           #else
                                           return (current_sp - shadow_alloc_size);
                                           #endif
                                           
                                       }
                                       
                                       // Memory Remanence Protection: zero-scrub stack region (P2-01)
                                       
                                       inline void tech_2601_scrub_stack(uintptr_t target_sp, uintptr_t current_sp) noexcept {
                                       
                                           if ((current_sp > target_sp) && (target_sp != 0x0000000000000000ULL)) {
                                           
                                               secure_zeroize(reinterpret_cast<void*>(target_sp), (current_sp - target_sp));
                                           }
                                       }
                                       
